P('التجربة قبل العبوة','رحلة العميل والتحقق',
 TB(['المحطة','الاحتياج','التطبيق والقياس'],[['التعرف','فهم هوية العطر سريعًا.','صورة واضحة واسم ثابت؛ نقيس الزيارة المؤهلة.'],['الاكتشاف','تجربة الرائحة وفهمها.','عينة وتعليمات بسيطة؛ نقيس الانتقال إلى شراء.'],['القرار','وضوح السعر والحجم والتوصيل.','صفحة منتج ومعلومات سياسة الاسترجاع.'],['الاستلام','منتج سليم وتجربة متقنة.','فحص تغليف؛ نقيس الكسر والتسرب والشكاوى.'],['العودة','الوصول إلى الرائحة نفسها بسهولة.','رسالة اختيارية بعد التجربة؛ نقيس إعادة الشراء حسب الدفعة.']]),
 N('<p>خطة بحث مقترحة: 30 مقابلة قصيرة لفهم اللغة والحاجة، ثم تجربة منظمة مع 60 مشاركًا للعينات، ثم 100 طلب مدفوع للتحقق من الاقتصاد التشغيلي. هذه عينات استطلاعية وليست تمثيلًا إحصائيًا لسكان السعودية.</p>'))

P('نفَس يتّسع','لوحة الإلهام',IMG('direction','لوحة اتجاه مولّدة: انكسار الزجاج، خفة النسيج، الورق المنقوش، والفضي مع الباذنجاني.'),
 T('<p>المصدر البصري هو انتقال العطر من التركيز إلى الانتشار: ضوء ينكسر عبر الزجاج، وطبقة خفيفة شفافة، وانحناءة تترك أثرًا ملموسًا على الورق. لا تعبّر صور الخامات عن مكونات العطر.</p>'))

P('من الحروف إلى رمز قابل للتكرار','فكرة الشعار',
 C('<h4>AEVU</h4><p>شعار حروفي هندسي بوزن واضح. تتقابل زوايا A وV مع انحناءة U، ويظل حرف E مقروءًا بلا اختزال مبهم. يقلل عدد التفاصيل من اعتماد الشعار على الحجم الكبير.</p><h4>إيڤو</h4><p>المعالجة العربية تحافظ على اتصال الحروف والهمزة أسفل الألف والنقطتين أسفل الياء والنقاط الثلاث فوق ڤ. تظهر تحت الإنجليزية في العبوة، مع إمكانية استخدامها مستقلة في محتوى عربي.</p>',
   '<h4>الرمز المساند</h4><p>ثلاث انحناءات U مفتوحة من الأعلى؛ تبدأ داخليًا ثم تتسع. يربط الرمز الاسم بالحركة التصورية للرائحة، ويتحول إلى نقش على العلبة والزجاج وتفصيل في المحتوى.</p><h4>مرحلة التنفيذ</h4><p>يُعاد رسم الشعار كمسارات متجهة مضبوطة عند إعداد حزمة الإنتاج. الرسم المولّد في العرض مرجع للاتجاه، ويحتاج ضبطًا هندسيًا واختبار طباعة قبل اعتماد أصغر قياس.</p>'))

P('قواعد تحفظ الوضوح','استخدام الشعار',
 TB(['القاعدة المقترحة','طريقة التطبيق'],[['مساحة الحماية','اترك حول الشعار مسافة تعادل ارتفاع حرف E واحدًا؛ تختبر بصريًا عند تنفيذ المسارات.'],['الحجم الصغير','نقطة اختبار أولية: 120 بكسل للشعار الثنائي رقميًا، و25 مم مطبوعًا. تكبّر إذا اندمجت النقاط.'],['النسخة الأساسية','باذنجاني على عاجي أو أخضر فاتح؛ والعاجي على باذنجاني للنسخة المعكوسة.'],['الرمز وحده','للنقش والتفاصيل الثانوية بعد ظهور الاسم في السياق نفسه.'],['منع التشويه','لا تمديد، ولا استبدال حرف برمز، ولا تغيير عدد النقاط أو الانحناءات.']]),
 N('<p>القيم حدود اختبار مبدئية وليست نتائج إنتاج موثقة. افحص الاسم العربي بالحجم الفعلي على ورق العلبة، والزجاج، وشاشة هاتف عادية؛ وضوح ڤ شرط للقبول.</p>'))

palette=[dict(name='باذنجاني عميق',hex='#382D42',rgb='56, 45, 66',role='لون الاسم والغطاء والكتل الأساسية؛ يعطي عمقًا بصريًا.'),dict(name='أخضر ضبابي',hex='#CCD8C2',rgb='204, 216, 194',role='العلبة والسطوح المساندة؛ يترجم الخفة والانتشار.'),dict(name='عاجي دافئ',hex='#F2EFE8',rgb='242, 239, 232',role='خلفية القراءة والعرض؛ يترك مجالًا للمنتج.'),dict(name='رمادي فضي',hex='#B6B9B7',rgb='182, 185, 183',role='مرجع رقمي للتفاصيل المعدنية؛ الخامة تعتمد بعينة مادية.')]
P('عمق يوازنه ضوء','الألوان وأسباب اختيارها',dict(type='palette',colors=palette),
 T('<p>نسبة استخدام مرشدة: 45% عاجي، 30% أخضر ضبابي، 20% باذنجاني، 5% فضي. تتغير بحسب التطبيق؛ القاعدة أن يبقى النص الداكن واضحًا. لا يستخدم الفضي للنص الصغير على العاجي.</p>'),
 N('<p>الأكواد مرجع RGB للشاشات. يضبط تحويل CMYK بعينة طباعة حسب الورق والمطبعة، ولا نستنتج لون حبر معدني من كود HEX. لا تُعد النسب وصفة ثابتة لكل تصميم.</p>'))

P('نصوص مقروءة في اللغتين','نظام الخطوط',
 C('<h4>العربية: IBM Plex Sans Arabic</h4><p>للعناوين والنصوص المساندة، بأوزان Regular وSemiBold. طابعه المعاصر ومقاييسه الواضحة يخدمان لغة العلامة دون زخرفة زائدة. يستخدم هذا الخط في متن الدليل. [8]</p><h4>الإنجليزية: Manrope</h4><p>للنصوص والأرقام والعناوين الإنجليزية المساندة. تتقارب هندسته الهادئة مع اتجاه الشعار. لا يُستبدل رسم الشعار بكتابة الاسم آليًا بهذا الخط. [9]</p>',
   '<h4>هرمية الاستخدام</h4><p>رقميًا: عنوان رئيسي 40–64 بكسل، فرعي 24–32، متن 16–18، معلومات ثانوية 14. تُراجع الأرقام حسب الشاشة. في المطبوعات يتقدم اختبار القراءة الفعلية على الالتزام بعدد نقاط ثابت.</p><h4>العربية والإنجليزية</h4><p>يضبط اتجاه الفقرات العربية من اليمين. تعزل الأسماء والأكواد اللاتينية باتجاه مستقل؛ لا تستخدم تباعد الحروف داخل الكلمات العربية. تراجع رخصة كل خط عند نقل ملفاته إلى حزمة الإنتاج. [8، 9]</p>'))

P('الخامة تحمل الفكرة','التكوين والتصوير',
 C('<h4>التكوين</h4><p>عنصر بطل واحد ومساحة تنفّس حوله. الاسم أعلى العبوة والنمط في الجزء السفلي. لا يتحول النمط إلى خلفية مزدحمة خلف النصوص. يظل ترتيب الاسم ومعلومات المنتج ثابتًا بين الزجاجة والعلبة.</p><h4>الضوء</h4><p>ضوء ناعم جانبي يبيّن سماكة الزجاج وملمس الورق. الانعكاس يخدم الشكل ولا يغطي الاسم. تستخدم الخلفيات العاجية والخضراء الخفيفة للعرض، والباذنجاني لبعض أغلفة المحتوى.</p>',
   '<h4>اختيار الصورة</h4><p>صورة واضحة للمنتج، ثم لقطة تفصيل للخامة، ثم سياق استخدام عند الحاجة. لا نضيف زهورًا أو أخشابًا توحي بمكونات غير موجودة في التركيبة الفعلية.</p><h4>الإفصاح البصري</h4><p>صورة المنتج ولوحة الاتجاه مولّدتان بالذكاء الاصطناعي لهذا المشروع. لا توجد صور مخزنية أو موكابات جاهزة من طرف ثالث في العرض. الصور نماذج تصورية، ولا تثبت أن العبوة صُنعت.</p>'))

P('العبوة الأولى','تطبيق الزجاجة',IMG('hero','زجاجة إيڤو وعلبتها: تطبيق تصوري مولّد بالذكاء الاصطناعي.'),
 N('<p>تصور الزجاج المنقوش والغطاء المصمم يحدد الطموح البصري. ميزانية البداية تفترض زجاجة قياسية قريبة من الشكل مع طباعة مخصصة؛ القالب الزجاجي الحصري غير مسعّر في النموذج.</p>'))

P('علبة تبدأ من الملمس','التغليف وقابلية التنفيذ',
 C('<h4>المظهر</h4><p>ورق أخضر ضبابي بملمس مطفي، واسم باذنجاني، ونقش ثلاثي مفتوح في الجزء السفلي. الجانب الباذنجاني يربط العلبة بالغطاء ويمنحها حضورًا عند عرضها مع منتجات أخرى.</p><h4>البنية</h4><p>تختار سماكة الورق والحاضنة الداخلية وفق وزن العبوة. تختبر مقاومة النقل والتسرب واحتكاك الطباعة. المقاسات النهائية تأتي من رسومات المورد وعينة مادية، لا من الصورة المولّدة.</p>',
   '<h4>المعلومات</h4><p>تخصص المساحة الخلفية أو السفلية لاسم المنتج والحجم والمكونات وبيانات الجهة المسؤولة والدفعة ومعلومات الصلاحية والتحذيرات اللازمة، بحسب متطلبات المنتج ومراجعة المختص. بيانات الواجهة في التصوّر لا تمثل ملصقًا نظاميًا مكتملًا. [3]</p><h4>تقليل التعقيد</h4><p>اعتماد مقاس واحد ولون علبة واحد في البداية، وحفظ الطباعة البارزة للرمز المساند. يؤجل التغليف الموسمي والقوالب الخاصة حتى ثبوت الطلب.</p>'))

P('تجربة رقمية بسيطة','المتجر والمحتوى',
 TB(['الموضع','المحتوى المقترح'],[['أعلى صفحة المنتج','صورة، اسم إيڤو، الشخصية العطرية المعتمدة، 50 مل، السعر الإجمالي.'],['قبل زر الشراء','وقت التوصيل، تكلفته، توفر المنتج، رابط واضح لسياسة الاسترجاع.'],['الاكتشاف','شرح العينة وكيفية التجربة؛ لا نطلب شراء منتج لا يعرف العميل عنه ما يكفي.'],['بعد الشراء','تأكيد التفاصيل والتتبع وخدمة العملاء برقم طلب قابل للرجوع.']]),
 C('<h4>نص إطلاق</h4><p>«إيڤو. نفَس يتّسع. اكتشف عطرًا يبدأ قريبًا، ثم يترك مساحة لحضورك».</p>', '<h4>نص من الفكرة إلى الهوية</h4><p>«من انحناءة U إلى أثرٍ يتكرر: حوّلنا فكرة انتشار العطر إلى نقش يوحّد الزجاجة والعلبة».</p>'))

P('نختبر قبل أن نوسع الإنفاق','خطة التسويق والإطلاق',
 TB(['المرحلة','العمل','ما يحدد الانتقال'],[['قبل البيع','محتوى فكرة الهوية والعينات وتجربة الفهم والنطق.','وضوح العرض واعتماد المنتج والمعلومات.'],['أول 100 طلب','اختبار رسالتين وصورتين من الأصول نفسها بميزانية مضبوطة.','قياس هامش الطلب والتسليم والشكاوى.'],['الأشهر 2–4','إعادة استهداف باختيار المستخدم، ومحتوى تجربة حقيقية بإذن أصحابها.','نتائج مدفوعة قابلة للتكرار.'],['الأشهر 5–12','رفع تدريجي للميزانية وربطها بقدرة التوريد والسيولة.','مساهمة لا تقل عن المستهدف وانخفاض مخاطر المخزون.']]),
 T(f'<p>يفترض النموذج تسويقًا متغيرًا بقيمة {n(a["marketing"])} ريال لكل طلب مشحون؛ أي {n(total_units*a["marketing"])} ريال خلال السنة الأولى، إضافة إلى 2,000 ريال شهريًا لإنتاج المحتوى ضمن الثابت و8,000 ريال لتجربة ما قبل الإطلاق ضمن التأسيس. لا تتكرر هذه البنود داخل بند آخر.</p>'))

P('كيف يربح المشروع؟','نموذج العمل وحدود الحساب',
 C('<h4>الوحدة المحاسبية</h4><p>طلب مشحون يحتوي زجاجة واحدة من 50 مل. يحتسب النموذج الإيراد بعد الخصم والاسترجاع، وتتحمل العلامة الشحن. لا إيراد للعينة أو الشحن أو الإهداء أو الاشتراك في الأساس.</p><h4>القيمة المضافة</h4><p>سعر المستهلك شامل 15% كافتراض لمنشأة مسجلة. يفصل النموذج الضريبة عن الإيراد ويفترض أن التكاليف المستحقة دون ضريبة مدخلات قابلة للاسترداد. لا يمثل حسابًا ضريبيًا أو جدول إقرار. [5]</p>',
   '<h4>المخزون والسيولة</h4><p>تستهلك تكلفة العبوة عند الشحن. المشتريات تدفع على دفعات ويظهر توقيتها منفصلًا في Excel. لا تخصم تكلفة المخزون الافتتاحي مرتين في الربح.</p><h4>النتيجة</h4><p>المعروض فائض تشغيلي قبل الإهلاك والتمويل والزكاة/ضريبة الدخل؛ تكاليف ما قبل الإطلاق وتجميد رأس المال موضحة منفصلة. الوضع النظامي والضريبي النهائي يحدده المختص وفق المنشأة. [3، 5، 6]</p>'),theme='dark')

