def block_html(b):
    ty=b['type']
    if ty=='text':return '<div class="text">'+b['html']+'</div>'
    if ty=='note':return '<aside>'+b['html']+'</aside>'
    if ty=='columns':return '<div class="columns">'+''.join('<div>'+s+'</div>' for s in b['items'])+'</div>'
    if ty=='table':return '<table><thead><tr>'+''.join('<th>'+x+'</th>' for x in b['headers'])+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+x+'</td>' for x in row)+'</tr>' for row in b['rows'])+'</tbody></table>'
    if ty=='image':return '<figure><img src="'+str(ROOT/'public'/b['src'].lstrip('/'))+'"/><figcaption>'+b['alt']+'</figcaption></figure>'
    if ty=='palette':return '<div class="palette">'+''.join('<div><i style="background:'+c['hex']+'"></i><h4>'+c['name']+'</h4><code>'+c['hex']+'</code><p>'+c['role']+'</p></div>' for c in b['colors'])+'</div>'
    raise ValueError(ty)
