css=css.replace('FONT_REG',str(FONTS/'IBMPlexSansArabic-Regular.ttf')).replace('FONT_BOLD',str(FONTS/'IBMPlexSansArabic-SemiBold.ttf')).replace('FONT_LATIN',str(FONTS/'Manrope[wght].ttf'))
hero=str(ASSETS/'hero.webp')
pages=[f'<section class="page cover"><div class="cover-copy"><div class="brand en">ATHR BRANDS / CONCEPT STUDY</div><div><h1>AEVU</h1><p class="arabic-name">إيڤو</p><h2>الاستراتيجية والهوية<br/>ودراسة الجدوى</h2><p>نفَس يتّسع.<br/>من الفكرة إلى المنتج والقرار التجاري.</p></div><div class="meta">مشروع تصوري من أثر<br/>السعودية · سبتمبر 2026 · الإصدار 1.0<br/>36 صفحة · ملف عربي كامل</div></div><img class="cover-image" src="{hero}"/></section>']
for s in sections:
    classes=['page',s['theme']]
    if s['page'] in [4,8,9,14,16,19,20,25,30,33]:classes.append('tint')
    if s['page'] in [23,24,25,26,27,28,29,32,33]:classes.append('compact')
    if s['page']==35:classes.append('sources')
    if s['page'] in (24,28):classes.append('budget')
    body=''.join(block_html(b) for b in s['blocks'])
    pages.append('<section class="'+' '.join(classes)+'"><div class="topline"><span>إيڤو · الاستراتيجية والهوية ودراسة الجدوى</span><span class="en">AEVU / ATHR BRANDS</span></div><p class="kicker">'+s['kicker']+'</p><h2>'+s['title']+'</h2><div class="page-content">'+body+'</div><div class="footer"><span>مشروع تصوري · افتراضات معلنة · سبتمبر 2026</span><span class="en">'+f'{s["page"]:02} / 36'+'</span></div></section>')
pages.append('<section class="page dark back"><p class="kicker">تصوّر من أثر</p><h1 class="en">AEVU</h1><h2>نفَس يتّسع.</h2><p class="note">تبدأ العلامة بفكرة يمكن شرحها، وتكتمل بمنتج وتجربة يمكن اختبارهما.<br/>هذا الدليل يربط الهوية بقرارات السوق والتكلفة والتشغيل.</p><div class="contents-list">'+''.join('<div class="contents-item"><b>'+t+'</b><span>'+str(s)+'–'+str(en)+'</span></div>' for _,t,_,s,en in chapters)+'</div><div class="footer"><span>أثر لصناعة الهويات البصرية</span><span class="en">www.athrbrands.sa · 36 / 36</span></div></section>')
report='<!DOCTYPE html><html lang="ar" dir="rtl"><head><meta charset="UTF-8"><title>إيڤو AEVU — الاستراتيجية والهوية ودراسة الجدوى</title><style>'+css+'</style></head><body>'+''.join(pages)+'</body></html>'
(BUILD/'report.html').write_text(report)
from weasyprint import HTML
doc=HTML(string=report,base_url=str(ROOT)).render()
if len(doc.pages)!=36:
    for i,pg in enumerate(doc.pages,1):
        texts=[getattr(b,'text','') for b in pg._page_box.descendants() if type(b).__name__=='TextBox']
        print(i,texts[:4],texts[-3:])
    raise ValueError(f'Unexpected page count {len(doc.pages)}')
overflows=[]
for i,page in enumerate(doc.pages,1):
    # Text inside page content must end before the reserved footer.
    for box in page._page_box.descendants():
        if type(box).__name__=='TextBox' and getattr(box,'element',None) is not None:
            if box.position_y+box.height>765 and i not in [1,36]:
                overflows.append((i,round(box.position_y+box.height),getattr(box,'text','')[:70]))
print('overflow candidates',overflows[:20])
doc.write_pdf(OUT/study['file'])
print('PDF',OUT/study['file'])
